import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

"use client";

import { createContext, type ReactNode, useContext } from "react";

export type Size = "xs" | "sm" | "md" | "lg" | "xl";

const SizeContext = createContext<Size | undefined>(undefined);

export function useSize(size?: Size) {
  const inherited = useContext(SizeContext);
  return size ?? inherited;
}

export function SizeProvider({
  size,
  children,
}: {
  size: Size | undefined;
  children: ReactNode;
}) {
  return <SizeContext value={size}>{children}</SizeContext>;
}

import type { Size } from "./size";

export const fieldSizeStyles = {
  xs: "[--field-h:1.75rem] [--field-px:0.5rem] [--field-radius:var(--radius-sm)] [--field-text:0.75rem] [--field-icon:0.875rem]",
  sm: "[--field-h:2.25rem] [--field-px:0.75rem] [--field-radius:var(--radius-md)] [--field-text:0.875rem] [--field-icon:1rem]",
  md: "[--field-h:2.75rem] [--field-px:0.875rem] [--field-radius:var(--radius-lg)] [--field-text:0.875rem] [--field-icon:1rem]",
  lg: "[--field-h:3rem] [--field-px:0.875rem] [--field-radius:var(--radius-lg)] [--field-text:0.875rem] [--field-icon:1rem]",
  xl: "[--field-h:3.5rem] [--field-px:1rem] [--field-radius:var(--radius-xl)] [--field-text:1rem] [--field-icon:1.25rem]",
} satisfies Record<Size, string>;

export const fieldHeight = "min-h-[var(--field-h,3rem)]";
export const fieldInnerHeight = "min-h-[calc(var(--field-h,3rem)-0.25rem)]";
export const fieldPaddingX = "px-[var(--field-px,0.875rem)]";
export const fieldRadius = "rounded-[var(--field-radius,var(--radius-lg))]";
export const fieldText =
  "text-base sm:text-[length:var(--field-text,0.875rem)] sm:[line-height:var(--tw-leading,1.25rem)]";
export const fieldIcon =
  "[&_svg:not([class*='size-'])]:size-[var(--field-icon,1rem)]";

export const fieldLabelStyles =
  "text-sm font-medium text-foreground [overflow-wrap:anywhere]";
export const fieldDescriptionStyles =
  "text-xs leading-5 text-muted-foreground [overflow-wrap:anywhere]";
export const fieldErrorStyles =
  "text-xs leading-5 text-destructive [overflow-wrap:anywhere] transition-[opacity,translate] duration-200 ease-out-quint starting:opacity-0 motion-safe:starting:-translate-y-1";

export const fieldInputStyles = `${fieldHeight} ${fieldRadius} ${fieldText} w-full cursor-text border border-input bg-card text-foreground shadow-[var(--shadow-card)] outline-none transition-[color,background-color,border-color,box-shadow] duration-150 ease-out-quint placeholder:text-muted-foreground/80 hover:border-primary/45 focus:border-ring focus:ring-1 focus:ring-ring invalid:border-destructive invalid:hover:border-destructive invalid:focus:border-destructive invalid:focus:ring-destructive [&[readonly]]:bg-muted/40 [&[readonly]]:hover:border-input disabled:cursor-not-allowed disabled:bg-muted disabled:opacity-60 disabled:hover:border-input`;

export const segmentedFieldStyles = `${fieldHeight} ${fieldRadius} flex min-w-0 items-center border border-input bg-card shadow-[var(--shadow-card)] transition-[color,background-color,border-color,box-shadow] duration-150 ease-out-quint hover:border-primary/45 focus-within:border-ring focus-within:hover:border-ring focus-within:ring-1 focus-within:ring-ring group-invalid:border-destructive group-invalid:hover:border-destructive group-invalid:focus-within:border-destructive group-invalid:focus-within:hover:border-destructive group-invalid:focus-within:ring-destructive group-data-[readonly]:bg-muted/40 group-data-[readonly]:hover:border-input group-disabled:bg-muted group-disabled:opacity-60 group-disabled:hover:border-input`;

export const fieldTriggerStyles = `${fieldIcon} group/trigger grid size-[calc(var(--field-h,3rem)-0.25rem)] shrink-0 cursor-pointer place-items-center rounded-[calc(var(--field-radius,var(--radius-lg))-0.125rem)] text-muted-foreground outline-none transition-[color,background-color,scale] duration-150 ease-out-quint hover:bg-muted hover:text-foreground pressed:bg-muted pressed:text-foreground focus-visible:-outline-offset-2 focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-ring disabled:cursor-default disabled:opacity-50`;

export const fieldChevronStyles =
  "grid place-items-center transition-transform duration-250 ease-out-quint group-aria-expanded/trigger:rotate-180 motion-reduce:transition-none";

"use client";

import {
  ListBox as AriaListBox,
  ListBoxItem as AriaListBoxItem,
  composeRenderProps,
  type ListBoxItemProps,
  type ListBoxProps,
} from "react-aria-components";
import { cn } from "./utils";

export function ListBox<T extends object>({
  className,
  ...props
}: ListBoxProps<T>) {
  return (
    <AriaListBox
      {...props}
      data-slot="list-box"
      className={composeRenderProps(className, (className) =>
        cn(
          "grid max-h-72 w-full min-w-0 gap-1 overflow-y-auto overscroll-contain rounded-lg border border-border bg-card p-1.5 shadow-[var(--shadow-card)] outline-none empty:min-h-24 empty:place-items-center empty:text-sm empty:text-muted-foreground focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-offset-2 focus-visible:outline-ring",
          className,
        ),
      )}
    />
  );
}

export function ListBoxItem({
  className,
  children,
  ...props
}: ListBoxItemProps) {
  return (
    <AriaListBoxItem
      {...props}
      data-slot="list-box-item"
      textValue={
        props.textValue ?? (typeof children === "string" ? children : undefined)
      }
      className={composeRenderProps(className, (className) =>
        cn(
          "group/item flex min-h-11 min-w-0 cursor-pointer items-center justify-between gap-3 rounded-md px-3 py-2 text-sm text-foreground outline-none [overflow-wrap:anywhere] transition-colors duration-150 ease-out-quint hover:bg-muted hover:duration-0 focus:bg-muted focus:duration-0 selected:bg-accent selected:text-accent-foreground disabled:cursor-default disabled:opacity-50 focus-visible:outline-1 focus-visible:outline-solid focus-visible:-outline-offset-1 focus-visible:outline-ring forced-colors:focus-visible:outline-2 forced-colors:focus-visible:-outline-offset-2",
          className,
        ),
      )}
    >
      {composeRenderProps(children, (content) => (
        <>
          {content}
          <SelectionMark />
        </>
      ))}
    </AriaListBoxItem>
  );
}

export function SelectionMark({ className }: { className?: string }) {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.6}
      strokeLinecap="round"
      strokeLinejoin="round"
      data-slot="selection-mark"
      className={cn("ms-auto size-4 shrink-0", className)}
    >
      <path
        d="M2.75 8 6.25 11.5 13.25 4.5"
        pathLength={1}
        className="[stroke-dasharray:1_2] [stroke-dashoffset:1.01] transition-[stroke-dashoffset] duration-200 ease-out-quint group-selected/item:[stroke-dashoffset:0] motion-reduce:transition-none"
      />
    </svg>
  );
}

"use client";

import {
  Dialog as AriaDialog,
  type DialogProps as AriaDialogProps,
  Popover as AriaPopover,
  type PopoverProps as AriaPopoverProps,
  composeRenderProps,
  DialogTrigger,
  type DialogTriggerProps,
  Heading,
  type HeadingProps,
  OverlayArrow,
  type OverlayArrowProps,
  Text,
  type TextProps,
} from "react-aria-components";
import { cn } from "./utils";
import { SizeProvider } from "./size";

export interface PopoverProps extends AriaPopoverProps {
  "data-slot"?: string;
}

export function PopoverTrigger(props: DialogTriggerProps) {
  return <DialogTrigger {...props} />;
}

export function Popover({
  className,
  children,
  "data-slot": dataSlot = "popover",
  ...props
}: PopoverProps) {
  return (
    <AriaPopover
      {...props}
      data-slot={dataSlot}
      className={composeRenderProps(className, (className) =>
        cn(
          "max-w-[calc(100vw-2rem)] overflow-auto overscroll-contain rounded-xl border border-border bg-popover p-4 text-popover-foreground [overflow-wrap:anywhere] shadow-[var(--shadow-float)] outline-none",
          // An arrow sits outside the panel, so the panel stops clipping.
          "has-[[data-slot=popover-arrow]]:overflow-visible",
          // React Aria sets data-entering and data-exiting once the placement is
          // known, then waits for these transitions before it unmounts the panel.
          "origin-(--trigger-anchor-point) transition-[opacity,scale,translate] duration-200 ease-out-quint",
          "placement-top:[--popover-shift:0_0.25rem] placement-bottom:[--popover-shift:0_-0.25rem] placement-left:[--popover-shift:0.25rem_0] placement-right:[--popover-shift:-0.25rem_0]",
          "entering:opacity-0 motion-safe:entering:scale-96 motion-safe:entering:[translate:var(--popover-shift)]",
          "exiting:opacity-0 exiting:duration-150 motion-safe:exiting:scale-98 motion-safe:exiting:[translate:var(--popover-shift)]",
          className,
        ),
      )}
    >
      {composeRenderProps(children, (children) => (
        <SizeProvider size={undefined}>{children}</SizeProvider>
      ))}
    </AriaPopover>
  );
}

export function PopoverArrow({
  className,
  ...props
}: Omit<OverlayArrowProps, "children">) {
  return (
    <OverlayArrow
      {...props}
      data-slot="popover-arrow"
      className={composeRenderProps(className, (className) =>
        cn("group/arrow", className),
      )}
    >
      <svg
        width={12}
        height={12}
        viewBox="0 0 12 12"
        aria-hidden="true"
        className="block fill-popover stroke-border group-placement-bottom/arrow:rotate-180 group-placement-left/arrow:-rotate-90 group-placement-right/arrow:rotate-90 forced-colors:fill-[Canvas] forced-colors:stroke-[CanvasText]"
      >
        <path d="M0 0 6 6 12 0" />
      </svg>
    </OverlayArrow>
  );
}

export function PopoverDialog({ className, ...props }: AriaDialogProps) {
  return (
    <AriaDialog
      {...props}
      data-slot="popover-dialog"
      className={cn("outline-none", className)}
    />
  );
}

export function PopoverTitle({ className, ...props }: HeadingProps) {
  return (
    <Heading
      {...props}
      slot="title"
      data-slot="popover-title"
      className={cn(
        "text-sm font-semibold leading-5 tracking-[-0.01em] [overflow-wrap:anywhere]",
        className,
      )}
    />
  );
}

export function PopoverDescription({ className, ...props }: TextProps) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="popover-description"
      className={cn(
        "mt-1 block text-sm leading-5 text-muted-foreground [overflow-wrap:anywhere]",
        className,
      )}
    />
  );
}

export function PopoverFooter({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      {...props}
      data-slot="popover-footer"
      className={cn("mt-4 flex flex-wrap justify-end gap-2", className)}
    />
  );
}

"use client";

import { XIcon } from "@phosphor-icons/react";
import {
  Button as AriaButton,
  Tag as AriaTag,
  TagGroup as AriaTagGroup,
  type TagGroupProps as AriaTagGroupProps,
  composeRenderProps,
  Label,
  TagList,
  type TagProps,
} from "react-aria-components";
import { cn } from "./utils";
import { type Size, SizeProvider, useSize } from "./size";

type TagSize = Extract<Size, "xs" | "sm" | "md">;

const tagSizeStyles = {
  xs: {
    tag: "min-h-7 rounded-md ps-2 text-xs",
    label: "py-0.5",
    remove: "size-6 rounded-sm [&_svg]:size-3",
  },
  sm: {
    tag: "min-h-9 ps-2.5",
    label: "py-1",
    remove: "size-8 [&_svg]:size-3",
  },
  md: {
    tag: "min-h-11 ps-3",
    label: "py-1.5",
    remove: "size-11 [&_svg]:size-3.5",
  },
} satisfies Record<TagSize, Record<"tag" | "label" | "remove", string>>;

export function TagGroup({
  className,
  size: sizeProp,
  ...props
}: AriaTagGroupProps & { size?: TagSize }) {
  const size = useSize(sizeProp);
  return (
    <SizeProvider size={size}>
      <AriaTagGroup
        {...props}
        data-slot="tag-group"
        data-size={size}
        className={cn("group/tag-group grid min-w-0 gap-2", className)}
      />
    </SizeProvider>
  );
}

export function TagGroupLabel({
  className,
  ...props
}: React.ComponentProps<typeof Label>) {
  return (
    <Label
      {...props}
      data-slot="tag-group-label"
      className={cn("text-sm font-medium", className)}
    />
  );
}

export function TagListView<T extends object>({
  className,
  ...props
}: React.ComponentProps<typeof TagList<T>>) {
  return (
    <TagList
      {...props}
      data-slot="tag-list"
      className={composeRenderProps(className, (className) =>
        cn(
          "flex min-w-0 flex-wrap gap-2 group-data-[size=xs]/tag-group:gap-1.5 empty:text-sm empty:text-muted-foreground",
          className,
        ),
      )}
    />
  );
}

export function Tag({
  className,
  children,
  size: sizeProp,
  ...props
}: TagProps & { size?: TagSize }) {
  const inherited = useSize(sizeProp);
  const size: TagSize =
    inherited === "xs" || inherited === "sm" ? inherited : "md";
  const styles = tagSizeStyles[size];
  return (
    <AriaTag
      {...props}
      data-slot="tag"
      data-size={size}
      textValue={
        props.textValue ?? (typeof children === "string" ? children : undefined)
      }
      className={composeRenderProps(className, (className) =>
        cn(
          "flex max-w-full cursor-default items-center gap-1 rounded-lg bg-card pe-1 text-sm font-medium shadow-[var(--shadow-card)] ring-1 ring-border/80 data-[selection-mode]:not-data-disabled:cursor-pointer outline-offset-4 outline-transparent transition-[color,background-color,box-shadow,scale,outline-color,outline-offset] duration-150 ease-out-quint hover:bg-muted motion-safe:pressed:scale-[0.96] selected:bg-accent selected:text-accent-foreground selected:ring-primary/35 disabled:cursor-default disabled:opacity-50 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring motion-reduce:outline-offset-2 forced-colors:border",
          styles.tag,
          className,
        ),
      )}
    >
      {(state) => (
        <>
          <span
            className={cn(
              "min-w-0 truncate",
              styles.label,
              state.allowsRemoving ? "pe-1" : "pe-2",
            )}
          >
            {typeof children === "function" ? children(state) : children}
          </span>
          {state.allowsRemoving && (
            <AriaButton
              slot="remove"
              data-slot="tag-remove"
              className={cn(
                "grid shrink-0 cursor-pointer place-items-center rounded-md text-muted-foreground outline-none transition-[color,background-color,scale] duration-150 ease-out-quint hover:bg-card hover:text-foreground motion-safe:pressed:scale-[0.96] focus-visible:outline-2 focus-visible:outline-solid focus-visible:-outline-offset-2 focus-visible:outline-ring",
                styles.remove,
              )}
            >
              <XIcon weight="bold" aria-hidden="true" />
            </AriaButton>
          )}
        </>
      )}
    </AriaTag>
  );
}

"use client";

import { CaretDownIcon } from "@phosphor-icons/react";
import type { ReactNode } from "react";
import {
  Button as AriaButton,
  ComboBox as AriaComboBox,
  type ComboBoxProps as AriaComboBoxProps,
  ComboBoxValue as AriaComboBoxValue,
  composeRenderProps,
  FieldError,
  Input,
  Label,
  ListBox,
  ListBoxItem,
  Text,
} from "react-aria-components";
import { cn } from "./utils";
import {
  fieldChevronStyles,
  fieldDescriptionStyles,
  fieldErrorStyles,
  fieldInputStyles,
  fieldLabelStyles,
  fieldSizeStyles,
  fieldTriggerStyles,
} from "./field-styles";
import { SelectionMark } from "./list-box";
import { Popover } from "./popover";
import type { Size } from "./size";
import { Tag, TagGroup, TagListView } from "./tag-group";

const comboBoxPopoverStyles =
  "w-[var(--trigger-width)] rounded-lg border-0 p-1.5 ring-1 ring-border/70";
const comboBoxItemStyles =
  "group/item flex min-h-11 cursor-pointer items-center justify-between gap-3 rounded-md px-2.5 py-2 text-sm outline-none transition-colors duration-150 ease-out-quint hover:bg-muted hover:duration-0 focus:bg-muted focus:duration-0 focus-visible:-outline-offset-1 focus-visible:outline-1 focus-visible:outline-solid focus-visible:outline-ring forced-colors:focus-visible:-outline-offset-2 forced-colors:focus-visible:outline-2 selected:bg-accent selected:text-accent-foreground disabled:cursor-default disabled:opacity-50";

export interface ComboBoxOption {
  id: string;
  name: string;
  description?: string;
}

type ComboBoxBaseProps<M extends "single" | "multiple"> = Omit<
  AriaComboBoxProps<ComboBoxOption, M>,
  "children" | "className"
> & {
  label?: string;
  description?: string;
  options?: ComboBoxOption[];
  placeholder?: string;
  size?: Size;
  className?: AriaComboBoxProps<ComboBoxOption, M>["className"];
  children?: AriaComboBoxProps<ComboBoxOption, M>["children"];
};

export interface ComboBoxProps extends ComboBoxBaseProps<"single"> {
  selectionMode?: "single";
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
}

export interface MultiSelectComboBoxProps
  extends ComboBoxBaseProps<"multiple"> {
  selectionMode: "multiple";
}

export function ComboBox(props: ComboBoxProps): React.ReactElement;
export function ComboBox(props: MultiSelectComboBoxProps): React.ReactElement;
export function ComboBox(props: ComboBoxProps | MultiSelectComboBoxProps) {
  if (props.selectionMode === "multiple") {
    return <MultipleComboBox {...props} />;
  }
  return <SingleComboBox {...props} />;
}

function SingleComboBox({
  label,
  description,
  options,
  placeholder = "Search options",
  size,
  className,
  children,
  value,
  defaultValue,
  onValueChange,
  ...props
}: ComboBoxProps) {
  return (
    <AriaComboBox
      {...props}
      data-slot="combo-box"
      data-size={size}
      selectedKey={value ?? props.selectedKey}
      defaultSelectedKey={defaultValue ?? props.defaultSelectedKey}
      onSelectionChange={(key) => {
        props.onSelectionChange?.(key);
        onValueChange?.(key === null ? "" : String(key));
      }}
      className={composeRenderProps(className, (className) =>
        cn(
          "group flex w-full min-w-0 flex-col gap-2",
          size && fieldSizeStyles[size],
          className,
        ),
      )}
    >
      {children ?? (
        <ComboBoxDefaults
          label={label}
          description={description}
          options={options}
          placeholder={placeholder}
        />
      )}
    </AriaComboBox>
  );
}

function MultipleComboBox({
  label,
  description,
  options,
  placeholder = "Search options",
  size,
  className,
  children,
  ...props
}: MultiSelectComboBoxProps) {
  return (
    <AriaComboBox
      {...props}
      data-slot="combo-box"
      data-size={size}
      className={composeRenderProps(className, (className) =>
        cn(
          "group flex w-full min-w-0 flex-col gap-2",
          size && fieldSizeStyles[size],
          className,
        ),
      )}
    >
      {children ?? (
        <ComboBoxDefaults
          label={label}
          description={description}
          options={options}
          placeholder={placeholder}
          multiple
        />
      )}
    </AriaComboBox>
  );
}

function ComboBoxDefaults({
  label,
  description,
  options,
  placeholder,
  multiple = false,
}: {
  label?: string;
  description?: string;
  options?: ComboBoxOption[];
  placeholder: string;
  multiple?: boolean;
}) {
  return (
    <>
      {label && <ComboBoxLabel>{label}</ComboBoxLabel>}
      <div className="relative flex items-center">
        <ComboBoxInput placeholder={placeholder} />
        <ComboBoxTrigger />
      </div>
      {multiple && <ComboBoxTags />}
      {description && <ComboBoxDescription>{description}</ComboBoxDescription>}
      <ComboBoxError />
      <Popover
        data-slot="combo-box-content"
        placement="bottom start"
        offset={7}
        maxHeight={268}
        className={comboBoxPopoverStyles}
      >
        <ListBox
          data-slot="combo-box-list-box"
          items={options ?? []}
          renderEmptyState={() => (
            <div className="px-3 py-3 text-sm text-muted-foreground">
              No matching options.
            </div>
          )}
          className="grid gap-1 outline-none"
        >
          {(option) => (
            <ListBoxItem
              data-slot="combo-box-item"
              id={option.id}
              textValue={option.name}
              className={comboBoxItemStyles}
            >
              <span className="min-w-0">
                <span className="block font-medium">{option.name}</span>
                {option.description && (
                  <span className="mt-0.5 block text-xs text-muted-foreground group-selected/item:text-accent-foreground">
                    {option.description}
                  </span>
                )}
              </span>
              <SelectionMark />
            </ListBoxItem>
          )}
        </ListBox>
      </Popover>
    </>
  );
}

export function ComboBoxTags({
  className,
  label = "Selected options",
  emptyText = "No options selected.",
}: {
  className?: string;
  label?: string;
  emptyText?: string;
}) {
  return (
    <AriaComboBoxValue<ComboBoxOption>
      data-slot="combo-box-tags"
      className={cn("min-w-0", className)}
    >
      {({ state }) => (
        <TagGroup
          aria-label={label}
          onRemove={(keys) => {
            if (Array.isArray(state.value)) {
              state.setValue(state.value.filter((key) => !keys.has(key)));
            }
          }}
        >
          <TagListView
            items={state.selectedItems.map((item) => ({
              id: item.key,
              name: item.textValue,
            }))}
            renderEmptyState={() => (
              <span className="text-sm text-muted-foreground">{emptyText}</span>
            )}
          >
            {(item) => (
              <Tag id={item.id} textValue={item.name}>
                {item.name}
              </Tag>
            )}
          </TagListView>
        </TagGroup>
      )}
    </AriaComboBoxValue>
  );
}

export function ComboBoxLabel({
  className,
  ...props
}: React.ComponentProps<typeof Label>) {
  return (
    <Label
      {...props}
      data-slot="combo-box-label"
      className={cn(fieldLabelStyles, className)}
    />
  );
}

export function ComboBoxInput({
  className,
  ...props
}: React.ComponentProps<typeof Input>) {
  return (
    <Input
      {...props}
      data-slot="combo-box-input"
      className={composeRenderProps(className, (className) =>
        cn(
          fieldInputStyles,
          "ps-[var(--field-px,0.875rem)] pe-[var(--field-h,3rem)]",
          className,
        ),
      )}
    />
  );
}

export function ComboBoxTrigger({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AriaButton>) {
  return (
    <AriaButton
      {...props}
      data-slot="combo-box-trigger"
      aria-label={props["aria-label"] ?? "Show options"}
      className={composeRenderProps(className, (className) =>
        cn(fieldTriggerStyles, "absolute inset-y-0 end-1 my-auto", className),
      )}
    >
      {children ?? <ComboBoxChevron />}
    </AriaButton>
  );
}

function ComboBoxChevron() {
  return (
    <span aria-hidden="true" className={fieldChevronStyles}>
      <CaretDownIcon />
    </span>
  );
}

export function ComboBoxContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Popover>) {
  return (
    <Popover
      {...props}
      data-slot="combo-box-content"
      placement={props.placement ?? "bottom start"}
      offset={props.offset ?? 7}
      maxHeight={props.maxHeight ?? 268}
      className={composeRenderProps(className, (className) =>
        cn(comboBoxPopoverStyles, className),
      )}
    >
      <ListBox
        data-slot="combo-box-list-box"
        className="grid gap-1 outline-none"
        renderEmptyState={() => (
          <div className="px-3 py-3 text-sm text-muted-foreground">
            No matching options.
          </div>
        )}
      >
        {children}
      </ListBox>
    </Popover>
  );
}

export function ComboBoxItem({
  className,
  children,
  ...props
}: Omit<React.ComponentProps<typeof ListBoxItem>, "children"> & {
  children: ReactNode;
}) {
  return (
    <ListBoxItem
